100	static_assert(kDecTcStages >= 1 && kDecTcStages <= 2,
101	              "SG_TUNED_DEC_GEMM_STAGES must be 1 (serial) or 2 (double-buffer)");
102	constexpr int kDecTcSmemA1 = wgs::kWgmmaAtomM * wgs::kWgmmaAtomK;   // 64*16 bf16
103	constexpr int kDecTcSmemB1 = SG_TUNED_TILE_N * wgs::kWgmmaAtomK;    // N*16 bf16
104	constexpr int kDecDwSplitK = SG_TUNED_DEC_DW_SPLITK;
105	static_assert(kDecDwSplitK >= 1, "SG_TUNED_DEC_DW_SPLITK must be >= 1");
106	
107	// Token-tile rows a CTA owns. Must be a multiple of 64 (wgmma atom M) AND of
108	// kSeq (so a tile boundary is a sample boundary — attention stays in-tile).
109	constexpr int kTileM = SG_TUNED_TILE_M;
110	static_assert(kTileM % wgs::kWgmmaAtomM == 0,
111	              "SG_TUNED_TILE_M must be a multiple of 64 (wgmma m64 atom)");
112	static_assert(kTileM % dec::kSeq == 0,
113	              "SG_TUNED_TILE_M must be a multiple of kSeq=4 (tile=sample boundary)");
114	constexpr int kAtomsM = kTileM / wgs::kWgmmaAtomM;   // stacked m64 atoms per tile
115	constexpr int kSamplesPerTile = kTileM / dec::kSeq;  // 32 for TILE_M=128
