117	// ── LN vector-grad partials layout (the 10 tile-local γ/β grads). Order MUST
118	//    match dec_layout tensor indices {6,7,8,9,18,19,20,21,26,27}. We store them
119	//    densely [10 x kD] per CTA; the P2 reduce maps them back by tensor index. ──
120	constexpr int kNumLnVec = 10;                 // n1_w,n1_b,n2_w,n2_b ×L + norm_w,norm_b
121	constexpr int kLnVecElems = kNumLnVec * dec::kD;   // 10 * 128 = 1280
122	// The dec_layout tensor index of each LN-vector slot, in our dense order.
123	__device__ __constant__ int kLnVecTensorIdx[kNumLnVec] = {
124	    6, 7, 8, 9,        // L0 n1.w, n1.b, n2.w, n2.b
125	    18, 19, 20, 21,    // L1 n1.w, n1.b, n2.w, n2.b
126	    26, 27             // norm.w, norm.b
127	};
