    //    every wgmma was followed by wait_group<0>, and the epilogue stores of
    //    atom a interleaved with atom a+1's first wgmma — ptxas saw "non-wgmma
    //    instructions defining accumulator registers between pipeline stages" and
    //    SERIALIZED (C7515). Here, for each k-step we issue ALL m_atoms wgmmas
    //    (atom0..atom{m-1}) BACK-TO-BACK into their OWN fp32 fragments before the
    //    single wait_group<0>. The atoms are INDEPENDENT (distinct M-rows, distinct
    //    accumulators, shared B-tile) → no accumulator RAW between them → the
    //    hardware overlaps their MMA execution in the tensor pipe, and no non-wgmma
    //    instruction sits between consecutive wgmmas of the group. The per-atom
    //    accumulation stays ASCENDING-k (k=0 overwrite, k>0 add) → bit-identical
    //    numerics + A/A/A determinism UNCHANGED. The ring now stages m_atoms A-tiles
    //    (one per atom, contiguous: slot sl, atom a at +a·kDecTcSmemA1) + ONE shared
    //    B-tile per k-step; the caller's smemA must hold kAtomsM·kDecTcStages tiles.

    // Stage k-tile: all m_atoms A-tiles (rows mbase0+a·64) + the shared B-tile, into
    // ring slot k % S. A-tiles packed [slot][atom]; B-tile [slot].
    auto stage_k = [&] (int k) {
        const int sl = k % S;
        for (int a = 0; a < m_atoms; ++a) {
            const int mbase = mbase0 + a * wgs::kWgmmaAtomM;
            stage_kmajor_tile<wgs::kWgmmaAtomM>(
                smemA + ((int64_t)sl * MaxAtomsM + a) * kDecTcSmemA1, k * wgs::kWgmmaAtomK,
                [&] (int mn, int kk) { return srcA(mbase + mn, kk); }, tid, nthreads);
        }
        stage_kmajor_tile<N>(
            smemB + (int64_t)sl * kDecTcSmemB1, k * wgs::kWgmmaAtomK,
            [&] (int mn, int kk) { return srcB(mn, kk); }, tid, nthreads);
    };
    // Issue ALL m_atoms wgmmas for staged slot k (k=0 overwrite, else accumulate).
    auto issue_k = [&] (int k) {
        const int sl = k % S;
        wgs::SmemDesc dB = wgs::make_desc_B_kmajor<N, wgs::kSwizzleNone>(
            smemB + (int64_t)sl * kDecTcSmemB1);
