                smemA + ((int64_t)sl * MaxAtomsM + a) * kDecTcSmemA1);
            if (k == 0) wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/0, 0, 0>(acc[a], dA, dB);
