    // k%S (async, overlapping in the tensor pipe), THEN stage tile k+1 into the
    // OTHER slot (its HBM loads overlap the MMAs), THEN wait_group<0> + sync. S=1
    // collapses to staging into the single slot AFTER the wait (serial, bit-exact).
    #pragma unroll 1
    for (int k = 0; k < k_steps; ++k) {
        if (in_wg0) { issue_k(k); wgs::wgmma_commit_group(); }
        if (S > 1) {
            if (k + 1 < k_steps) stage_k(k + 1);
            if (in_wg0) wgs::wgmma_wait_group<0>();
            __syncthreads();
        } else {
            if (in_wg0) wgs::wgmma_wait_group<0>();
            __syncthreads();
            if (k + 1 < k_steps) { stage_k(k + 1); __syncthreads(); }
        }
    }
