struct DecTcSmem {
    // GEMM K-loop ring. The M-atom-interleaved wgmma pipeline stages kAtomsM
    // A(64×16) tiles per slot (one per stacked m64 atom, issued back-to-back into
    // independent fp32 fragments so the tensor pipe overlaps them — clears ptxas
    // C7515) + ONE shared B(N×16) tile per slot. Layout: A-tiles packed
    // [slot][atom] (slot s, atom a at sA + (s*kAtomsM + a)*64*16); B [slot] at
    // sB + s*N*16. At S=2, kAtomsM=2, N=128 the ring is 2·(2·2KB + 4KB)=16KB;
    // DecTcSmem total ~17.5KB ≪ the 48KB static cap. (The dW path uses
    // MaxAtomsM=1 → it only touches the first A-tile of each slot.)
    __nv_bfloat16 sA[dectc::kDecTcStages * dectc::kAtomsM * 64 * 16];
    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
    float red[256];
    dectc::DecDwSpec spec[9];
};

