def _lossval(loss):
    if loss is None:
        return 0.0
    if isinstance(loss, (list, tuple)):
        loss = loss[0]
    try:
        return float(loss)
    except Exception:
        try:
            return float(loss.reshape(-1)[0].item())
        except Exception:
            return 0.0

